"""Documentary timing/geometry audit only. No image or statistical engine calls."""
from pathlib import Path
import datetime,hashlib,html,json
R=Path(__file__).resolve().parent;P=R.parent
A=P/'image-context-v4';B=P/'sh-qok-image-context-v4'
def load(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def save(n,x):(R/n).write_text(json.dumps(x,indent=2,ensure_ascii=False),encoding='utf-8')
def digest(b):return hashlib.sha256(b).hexdigest()
def snapshot(p,relative):
 b=p.read_bytes();out=R/'snapshots'/relative;out.parent.mkdir(parents=True,exist_ok=True)
 if out.exists():assert out.read_bytes()==b,'Preserve previous snapshot; use new audit for changed source'
 else:out.write_bytes(b)
 return dict(source=str(p),copy=str(out.relative_to(R)),bytes=len(b),sha256=digest(b))
assert not (R/'AUDIT.json').exists(),'One-shot snapshot; preserve previous audit'
archive=A/'registration/hold-snapshots/v4.2-20261025T020312Z';past=load(archive/'AUDIT.json');preservation=[]
for name,meta in past['preserved_files'].items():
 p=archive/name;b=p.read_bytes();assert digest(b)==meta['sha256'];assert len(b)==meta['bytes'];preservation.append(snapshot(p,Path('original-hold')/name))
preservation.append(snapshot(archive/'AUDIT.json',Path('original-hold/AUDIT.json')))
reg=load(archive/'registration/REGISTRATION.json');geom=load(archive/'registration/SHARED-LINE-GEOMETRY.json');assert len(geom['lines'])==45 and len(reg['accepted'])==8
assert len({x['shared_line_id'] for x in geom['lines']})==45
reading_counts={r:sum(x['reading']==r for x in reg['accepted']) for r in ['H','F']};assert reading_counts=={'H':4,'F':4}
receipt=load(A/'AMENDMENT-v4.2-RECEIPT.json');assert digest((A/receipt['amendment_file']).read_bytes())==receipt['amendment_sha256']
assert digest((B/'AMENDMENT-v4.2-effect-scale.md').read_bytes())==receipt['amendment_sha256']
source_paths=[(A/'AMENDMENT-v4.2-effect-scale.md','analyst/AMENDMENT-v4.2-effect-scale.md'),(A/'AMENDMENT-v4.2-RECEIPT.json','analyst/AMENDMENT-v4.2-RECEIPT.json'),(A/'AMENDMENT-v4.1-agreement-unit.md','analyst/AMENDMENT-v4.1-agreement-unit.md'),(A/'registration/GEOMETRY-RETENTION-DECISION.json','analyst/GEOMETRY-RETENTION-DECISION.json'),(A/'registration/GEOMETRY-RETENTION-DECISION.txt','analyst/GEOMETRY-RETENTION-DECISION.txt'),(A/'registration/REGISTRAR-HOLD-RECEIPT.json','analyst/REGISTRAR-HOLD-RECEIPT.json'),(A/'registration/RESUME-AUTHORIZATION.json','analyst/RESUME-AUTHORIZATION.json'),(B/'V4.2-FREEZE.json','parallel/V4.2-FREEZE.json'),(B/'CLI-HOLD-RECEIPT.json','parallel/CLI-HOLD-RECEIPT.json'),(B/'ISOLATION-QUALIFICATION.json','parallel/ISOLATION-QUALIFICATION.json')]
for p,rel in source_paths:
 if p.exists():preservation.append(snapshot(p,Path(rel)))
# Preserve append-only phase history at an exact byte prefix; later phases are outside snapshot.
log=B/'PHASES.jsonl';raw=log.read_bytes();prefix=b'';phase_checks=[]
for i,line in enumerate(raw.splitlines(keepends=True),1):
 d=json.loads(line);old=d.get('previous_log_sha256');ok=old is None or old==digest(prefix);phase_checks.append(dict(line=i,phase=d['phase'],utc=d.get('utc'),previous_prefix_matches=ok));prefix+=line
assert all(x['previous_prefix_matches'] for x in phase_checks)
out=R/'snapshots/parallel/PHASES.prefix.jsonl';out.write_bytes(raw);phase_receipt=dict(source=str(log),snapshot=str(out.relative_to(R)),bytes=len(raw),sha256=digest(raw),append_only_scope=True,checks=phase_checks)
save('PHASE-HISTORY-CHECK.json',phase_receipt)
sources=load(A/'registration/GEOMETRY-RETENTION-DECISION.json');assert sources['retained']['sha256']==digest((archive/'registration/SHARED-LINE-GEOMETRY.json').read_bytes())
isolation=load(B/'ISOLATION-QUALIFICATION.json');assert isolation['status']=='PASS'
for role in isolation['roles']:assert role['status']=='PASS' and all(role['mxc_canaries'].values())
audit=dict(checked_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),status='TIMING_EXCEPTION_CONFIRMED; RETENTION_SUPPORTED; CONTINUATION_PROPOSED',amendment_sha256=receipt['amendment_sha256'],original_timing_requirement_met=False,original_hold_files_verified=len(past['preserved_files']),original_geometry=dict(shared_physical_lines=45,physical_blocks=4,reading_specific_block_maps=reading_counts,reviewed_pages_saved=10,additional_images_seen_without_saved_geometry=['f10v','f11r','f11v','f25r'],scope='Partial source review, not an inferential subset'),no_ratings_at_v4_2_freeze='Both analyst-role receipts report zero picture-rating inference before amendment; no claim about inaccessible external activity',earlier_registration='Occurred before v4.2; source-only registrar. Timing failure cannot be retroactively fixed.',ledger_revision='Existing retention audit finds changes to explanatory/exclusion metadata only; accepted geometry, mappings and drop decisions preserved',later_authorizations=dict(coordinator='User explicitly authorized retaining45lines and resuming the full blind-registration queue under v4.1/v4.2.',parallel='User explicitly authorized v4.2 freeze with exception and lifting hold, conditional on isolation before independent registration/rating.',effect='This audit does not revoke those approvals or itself issue a new operational release.'),phase_prefix=phase_receipt,preservation=preservation,analysis='No ratings, registration, support calculation, controls, outcome join, OR/RD calculation or scoring performed by this audit',v103='PARKED',Rosettes='No new leave-out grids',limitations=['Documentary and hash verification, not an independent pixel re-review.','Later active-chat phases may append after this snapshot; no blanket claim that no work has subsequently run.','Empirical CLI canaries validate tested paths/roles, not all conceivable access or absence of model pretraining knowledge.'])
save('AUDIT.json',audit)
proposal=dict(status='FROZEN PROPOSAL ONLY; NOT A NEW WORKFLOW RELEASE',title='Continuation with disclosed pre-registration timing exception',basis='Retain source-only geometry already accepted and explicitly authorized by user; preserve complete chronology. v4.1 stands; v4.2 is the analysis scale/control amendment.',required_disclosure='PROSPECTIVE IN IMAGE VARIABLE ONLY — text events exposed. Initial blind geometry/registration preceded v4.2; timing exception disclosed and retained by user authorization.',retention=['Keep the45original shared lines,4physical blocks and4H+4F maps as a sealed version. Do not replace/re-measure them merely to reset the clock.','Do not call the45lines the test cohort. Continue the original full-page queue with all exclusions, unknown/unreviewed blocks and mismatches.','Keep old extraction failures, count discrepancies, unsaved-image-view receipt, all holds, releases and phase prefixes. Source-only corrections require new versions and reasons, never effect/support/agreement-driven changes.'],geometry_release_gate=['Before deriving labels, freeze one primary shared physical-line geometry and its separate H/F crosswalk plus full cohort/exclusion manifest.','There are two operational registration workflows. State which supplies the primary geometry and which is independent QA/alternate evidence. Do not pool them or choose the one giving better agreement, support, effects or p-values. No automatic reclassification is made by this proposal.','Seal the completed geometry/crosswalk without either picture-box set or text outcomes. Every unmatched reading unit remains an explicit H/F-specific drop.'],rating_release_gate=['Use the existing exact picture-only manual; raters do not mark writing. No amendment rationale, source text outcomes, analyst chats or other rater outputs in their inputs.','Verify separate runtime/memory/access/input manifests for both raters; current finite-role isolation tests pass, but actual execution must use the same constraints and log model/version and each call.','Bind the primary cohort, manual and execution/input hashes before first picture-rating call. Preserve blind outputs append-only; no reuse across raters. This proposal performs no dispatch.'],after_rating=['Apply each picture-box set independently to the SAME frozen shared geometry. Freeze deterministic distance/tie/OT-merge/wrap conventions before deriving labels.','Judge original-rater G6/G2>=.60 before adjudication, per v4.1. No adjudication rescue of failed initial gates.','Keep original outcome-blind support and H/F/scribe strata. Join only after its prerequisites. The>=10qok rule is post-join abstain-only and can never admit a new cell.','Implement MHlogOR/RBG conventions and synthetic controls under a separate code/input freeze; qualify base-rate null and both OR-scale positives before any hypothesis scoring. No assertion that changing scale alone validates the permutation engine.','Specify how label-specific nuisance base rates are obtained without silently opening the outcome join before its allowed phase, and how abstention is handled in simulated/permuted runs; do not improvise after labels/results.','Keep RD and arm base rates descriptive beside OR; report disagreements without selecting a winning scale.'],locks=['Existing user releases remain limited to their explicit scope. This document neither starts ratings nor waives any pending gate.','v103 remains PARKED; no Rosettes leave-out grids.','No optional retrospective OR companion is run by this audit.'],remaining_decisions=['Bind a single primary geometry/crosswalk and the role of the parallel registration.','Verify actual per-call rater constraints before use and freeze any remaining implementation conventions before their dependent phase.'])
save('CONTINUATION-PROPOSAL.json',proposal)
save('PROPOSAL-FREEZE.json',dict(utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),audit_sha256=digest((R/'AUDIT.json').read_bytes()),proposal_sha256=digest((R/'CONTINUATION-PROPOSAL.json').read_bytes()),auditor_sha256=digest(Path(__file__).read_bytes()),phase_snapshot_sha256=digest(raw),status='Frozen audit/proposal snapshot, not a claim that earlier phase order was satisfied'))
e=html.escape
def table(headers,rows):return '<table><tr>'+''.join('<th>'+e(x)+'</th>' for x in headers)+'</tr>'+''.join('<tr>'+''.join('<td>'+e(str(x))+'</td>' for x in r)+'</tr>' for r in rows)+'</table>'
body='<p>VOYNICH · v4.2 TIMING RESOLUTION</p><h1>Retain the evidence; disclose the exception</h1><p class="notice"><strong>The requested pre-registration v4.2 freeze was NOT met.</strong> The defensible resolution is explicit retention with a timing exception, not retrospective repair. Later user approvals to retain and resume are preserved. v103 remains PARKED.</p>'
body+='<h2>What ran before the amendment</h2>'+table(['Phase','Audited record'],[['Inputs','168ready source images;34withheld panel-registration folios'],['Source geometry review','10saved page reviews;4additional viewed images without saved geometry'],['Accepted registration','45shared physical lines;4physical blocks;4H and4F block maps'],['Earlier failures','Fleck-scale candidate failure, row-count mismatches and ambiguities retained'],['Picture ratings','No rating inference reported before the amendment freeze'],['Later scientific phases','No image-label derivation, agreement, support, controls, outcome join or hypothesis test reported before that freeze']])
body+='<p>Registration was source-only, without picture-box sets or text-event outcomes, according to task/input and registrar receipts. That supports retention but does not turn the missed timing requirement into compliance. The accepted geometry is not the whole cohort or independently re-reviewed by this audit.</p>'
body+='<h2>What was preserved and verified</h2><p>Verified all '+str(len(past['preserved_files']))+' original held artifact hashes, copied the sealed hold records into this audit, reconciled45unique physical lines and separate H/F block maps, and checked the complete '+str(len(phase_checks))+'-entry phase-hash prefix. Metadata-only ledger changes and failed proposals remain visible. The phase log was copied, not rewritten.</p><p>The original registrar receipt also records four additional viewed images with no saved geometry. They remain exposure history; they are not newly unseen material. No source-image pixels were opened by this audit.</p>'
body+='<h2>Later user authorizations are separate events</h2><p>The coordinating chat received an explicit instruction to retain the45lines and resume the full blind-registration queue. The parallel CLI chat received an explicit instruction to freeze v4.2 with the exception and lift its hold subject to isolation. This audit preserves those permissions; it neither issues another release nor labels later work as pre-amendment. The CLI role-specific context and tested-path isolation checks now report PASS; that is a finite runtime check.</p>'
body+='<h2>Frozen proposed path forward</h2><ol><li><strong>Retain the45lines as a sealed version.</strong> Continue the full queue; preserve every drop and source-only correction with a reason/version.</li><li><strong>Freeze one primary geometry and two reading crosswalks.</strong> Assign the parallel registration a declared QA/alternate role before picture labels are used. Never select the run by agreement, support or effect.</li><li><strong>Bind the rating inputs and runtime.</strong> Separate raters receive only permitted images/manual, with memory/access boundaries, model versions and actual call inputs logged. Amendment rationale stays analyst-only.</li><li><strong>Keep v4.1’s agreement gates.</strong> Apply both picture-box sets to the same frozen writing geometry; original-rater G6/G2 precede adjudication.</li><li><strong>Qualify v4.2’s analysis before scoring.</strong> Freeze implementation conventions and nuisance-input provenance; test base-rate null and OR-scale positives. Keep post-join10-qok abstention one-way. Preserve RD/OR disagreements and every failed gate.</li></ol><p>This proposal is frozen, but it is not a dispatch or a waiver. The primary-geometry role across the two workflows still needs to be explicit. The old timeline can never be made fully pre-registration prospective by rerunning measurement now.</p>'
body+='<p>Required later disclosure: <strong>'+e(proposal['required_disclosure'])+'</strong></p><p><a href="AUDIT.json">Detailed audit and preserved-file manifest</a> · <a href="PHASE-HISTORY-CHECK.json">Phase-prefix chain</a> · <a href="CONTINUATION-PROPOSAL.json">Frozen continuation proposal</a> · <a href="PROPOSAL-FREEZE.json">Audit/proposal hashes</a> · <a href="../image-context-v4/registration/GEOMETRY-RETENTION-DECISION.txt">Existing retention decision</a> · <a href="../image-context-v4/AMENDMENT-v4.2-effect-scale.md">Original v4.2</a></p><p>Read-only documentary audit of scientific sources; no ratings, registrations, support, controls or scoring executed. No new Rosettes grids. Browser appearance unreviewed.</p>'
css='<style>body{max-width:1100px;margin:auto;padding:30px;background:#f5f2e9;color:#203f35;font:17px/1.6 system-ui}h1{font-size:32px;line-height:1.2}h2{margin-top:30px}.notice{background:#e0e9d8;padding:16px}table{border-collapse:collapse;width:100%;font-size:15px}th,td{padding:10px;border-bottom:1px solid #bac9bb;text-align:left;vertical-align:top}li{margin:12px 0}a{color:inherit}</style>'
(R/'report.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>v4.2 timing audit and frozen continuation proposal</title>'+css+'<main>'+body+'</main></html>',encoding='utf-8')
for x in preservation:assert digest((R/x['copy']).read_bytes())==x['sha256']
assert load(P/'v103-qualification-v104/PARKED.json')['status']=='PARKED_BY_USER'
save('VERIFICATION.json',dict(held_artifact_hashes='PASS',held_artifact_count=len(past['preserved_files']),shared_line_count=45,reading_specific_block_maps=reading_counts,phase_prefix_chain='PASS',phase_entries=len(phase_checks),amendment_copies_identical=True,source_history_rewritten=False,original_sources_modified=False,rating_calls_dispatched=0,registration_or_statistical_engines_executed=0,v103='PARKED',Rosettes_leave_out_grids=0))
save('DELIVERY-HASHES.json',{p.name:digest(p.read_bytes()) for p in R.iterdir() if p.is_file() and p.name!='DELIVERY-HASHES.json'})
print(json.dumps(dict(held_files=len(past['preserved_files']),shared_lines=45,H_blocks=4,F_blocks=4,phase_entries=len(phase_checks),timing='Exception retained, not cured',proposal='FROZEN',v103='PARKED')))
